We have a few options:

*Option 1*

Boost notes that have been migrated to country-specific address form. We can do this in two ways:



*Option 1a*

We boost those notes that have an address form and the address form type is _not_ {{legacy}}:

*ES Query - Option 1a*

{code:json}{
    "size": 1,
    "sort": [
        {
            "_score": {
                "order": "desc"
            }
        },
        {
            "created_at": {
                "order": "desc"
            }
        }
    ],
    "query": {
        "function_score": {
            "query": {
                "bool": {
                    "filter": [
                        {
                            "term": {
                                "user_id": 7952491
                            }
                        },
                        {
                            "terms": {
                                "order_state": [
                                    "delivered",
                                    "rejected",
                                    "failed"
                                ]
                            }
                        }
                    ],
                    "must_not": [
                        {
                            "term": {
                                "delivery_address_source": "cs_agent"
                            }
                        }
                    ],
                    "should": [
                        {
                            "term": {
                                "final_delivery_full_address.keyword": "Str. Petru Rares 15, Bucharest 011101"
                            }
                        },
                        {
                            "geo_distance": {
                                "distance": "60m",
                                "final_delivery_coordinates": {
                                    "lat": 44.451134,
                                    "lon": 26.072378
                                }
                            }
                        },
                        {
                            "term": {
                                "delivery_place_id": "internal|openaddresses:address:ro/bucharest:85974e79c3b1bd70"
                            }
                        }
                    ],
                    "minimum_should_match": 1
                }
            },
            "functions": [
                {
                    "filter": {
                        "bool": {
                            "must_not": {
                                "term": {
                                    "final_delivery_address_form.type": "legacy"
                                }
                            },
                            "must": {
                                "exists": {
                                    "field": "final_delivery_address_form.type"
                                }
                            }
                        }
                    },
                    "weight": 60
                },
                {
                    "filter": {
                        "term": {
                            "final_delivery_full_address.keyword": "Str. Petru Rares 15, Bucharest 011101"
                        }
                    },
                    "weight": 50
                },
                {
                    "filter": {
                        "term": {
                            "delivery_place_id": "internal|openaddresses:address:ro/bucharest:85974e79c3b1bd70"
                        }
                    },
                    "weight": 50
                }
            ],
            "score_mode": "max",
            "boost_mode": "replace"
        }
    }
}{code}

The downside to this is that, in case we migrated form a {{v_current}} to a  {{v_next}} form, {{v_next}} won’t get prioritised against {{v_current}}.

*Option 1b*

We explicitly construct a query that targets the latest version of the country-specific address form:

*ES Query - Option 1b*

{code:json}{
    "size": 3,
    "sort": [
        {
            "_score": {
                "order": "desc"
            }
        },
        {
            "created_at": {
                "order": "desc"
            }
        }
    ],
    "query": {
        "function_score": {
            "query": {
                "bool": {
                    "filter": [
                        {
                            "term": {
                                "user_id": 7952491
                            }
                        },
                        {
                            "terms": {
                                "order_state": [
                                    "delivered",
                                    "rejected",
                                    "failed"
                                ]
                            }
                        }
                    ],
                    "must_not": [
                        {
                            "term": {
                                "delivery_address_source": "cs_agent"
                            }
                        }
                    ],
                    "should": [
                        {
                            "term": {
                                "final_delivery_full_address.keyword": "Str. Petru Rares 15, Bucharest 011101"
                            }
                        },
                        {
                            "geo_distance": {
                                "distance": "60m",
                                "final_delivery_coordinates": {
                                    "lat": 44.451134,
                                    "lon": 26.072378
                                }
                            }
                        },
                        {
                            "term": {
                                "delivery_place_id": "internal|openaddresses:address:ro/bucharest:85974e79c3b1bd70"
                            }
                        }
                    ],
                    "minimum_should_match": 1
                }
            },
            "functions": [
                {
                    "filter": {
                        "term": {
                            "final_delivery_address_form.type": "v1_ro"
                        }
                    },
                    "weight": 60
                },
                {
                    "filter": {
                        "term": {
                            "final_delivery_full_address.keyword": "Str. Petru Rares 15, Bucharest 011101"
                        }
                    },
                    "weight": 50
                },
                {
                    "filter": {
                        "term": {
                            "delivery_place_id": "internal|openaddresses:address:ro/bucharest:85974e79c3b1bd70"
                        }
                    },
                    "weight": 50
                }
            ],
            "score_mode": "max",
            "boost_mode": "replace"
        }
    }
}{code}

The downside to this is that each time we bump address form versions, we’ll have to update the notes-matching query, otherwise migration from {{v_current}} to {{v_next}} will suffer from the same _apparent_ loss of notes.

*Option 2*

We drop any boost to {{place_id}} or textual matching, and simply prioritise the _latest_ order that is either in range, matches by {{place_id}} or matches by address text.

*ES Query - Option 2*

{code:json}{
    "size": 3,
    "sort": [
        {
            "_score": {
                "order": "desc"
            }
        },
        {
            "created_at": {
                "order": "desc"
            }
        }
    ],
    "query": {
        "function_score": {
            "query": {
                "bool": {
                    "filter": [
                        {
                            "term": {
                                "user_id": 7952491
                            }
                        },
                        {
                            "terms": {
                                "order_state": [
                                    "delivered",
                                    "rejected",
                                    "failed"
                                ]
                            }
                        }
                    ],
                    "must_not": [
                        {
                            "term": {
                                "delivery_address_source": "cs_agent"
                            }
                        }
                    ],
                    "should": [
                        {
                            "term": {
                                "final_delivery_full_address.keyword": "Str. Petru Rares 15, Bucharest 011101"
                            }
                        },
                        {
                            "geo_distance": {
                                "distance": "60m",
                                "final_delivery_coordinates": {
                                    "lat": 44.451134,
                                    "lon": 26.072378
                                }
                            }
                        },
                        {
                            "term": {
                                "delivery_place_id": "internal|openaddresses:address:ro/bucharest:85974e79c3b1bd70"
                            }
                        }
                    ],
                    "minimum_should_match": 1
                }
            },
            "functions": [
                {
                    "filter": {
                        "term": {
                            "final_delivery_address_form.type": "v1_ro"
                        }
                    },
                    "weight": 60
                },
                {
                    "filter": {
                        "term": {
                            "final_delivery_full_address.keyword": "Str. Petru Rares 15, Bucharest 011101"
                        }
                    },
                    "weight": 50
                },
                {
                    "filter": {
                        "term": {
                            "delivery_place_id": "internal|openaddresses:address:ro/bucharest:85974e79c3b1bd70"
                        }
                    },
                    "weight": 50
                }
            ],
            "score_mode": "max",
            "boost_mode": "replace"
        }
    }
}{code}

This greatly simplifies the logic and doesn’t require any modifications once we update address form versions. However, the risk is here that we incorrectly match notes that are associated to a different address (if, for example, an eater alternately orders at two nearby locations, each having its own notes, we will consistently incorrectly match the notes).

Worth noting that *Option 1a* and *Option 1b* also carry this risk, but it will be restricted to only one occasion (i.e. the first time the _second_ location is selected, we will incorrectly match the notes of the already migrated _first_ location; once the second location’s notes are migrated, the incorrect matching will no longer continue).

